package com.yeyamo_mobile.api.feed_service.infrastructure.cache;import java.time.Duration;import java.util.Optional;import org.slf4j.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.stereotype.Component;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.feed_service.application.FeedPage;import com.yeyamo_mobile.api.feed_service.application.port.FeedCachePort;
@Component public class RedisFeedCacheAdapter implements FeedCachePort{private static final Logger log=LoggerFactory.getLogger(RedisFeedCacheAdapter.class);private static final String VERSION="feed:version";private final StringRedisTemplate redis;private final ObjectMapper mapper;private final Duration ttl;public RedisFeedCacheAdapter(StringRedisTemplate r,ObjectMapper m,@Value("${feed.cache.ttl-seconds:60}")long seconds){redis=r;mapper=m;ttl=Duration.ofSeconds(seconds);}
 public Optional<FeedPage>get(String user,int page,int size){try{String v=redis.opsForValue().get(key(user,page,size));return v==null?Optional.empty():Optional.of(mapper.readValue(v,FeedPage.class));}catch(Exception e){log.debug("Feed cache read unavailable: {}",e.getMessage());return Optional.empty();}}public void put(FeedPage page){try{redis.opsForValue().set(key(page.userId(),page.page(),page.size()),mapper.writeValueAsString(page),ttl);}catch(Exception e){log.debug("Feed cache write unavailable: {}",e.getMessage());}}public void invalidate(){try{redis.opsForValue().increment(VERSION);}catch(RuntimeException e){log.debug("Feed cache invalidation unavailable: {}",e.getMessage());}}private String key(String user,int p,int s){String v=redis.opsForValue().get(VERSION);return "feed:"+(v==null?"0":v)+":"+user+":"+p+":"+s;}}
